/**
 * Reformat a backend-stage-*.csv into the "simple" share format Husam used
 * for last week's team message: just Question / Answer Length / STAGE table /
 * Total, no User or Run 1 wrapper, with one blank line between blocks.
 *
 * Usage:
 *   node scripts/build-simple-stage-csv.js <input.csv> [output.csv]
 *
 * Generated by Claude.
 */

const fs = require('fs')
const path = require('path')

const inputPath = process.argv[2]
if (!inputPath) {
  console.error('Usage: node scripts/build-simple-stage-csv.js <input.csv> [output.csv]')
  process.exit(1)
}
const outputPath =
  process.argv[3] ||
  path.join(
    path.dirname(inputPath),
    path.basename(inputPath, path.extname(inputPath)) + '-simple.csv'
  )

const raw = fs.readFileSync(inputPath, 'utf8').replace(/\r\n/g, '\n')

function parseCsvLine(line) {
  const out = []
  let cur = ''
  let inQuotes = false
  for (let i = 0; i < line.length; i++) {
    const c = line[i]
    if (inQuotes) {
      if (c === '"' && line[i + 1] === '"') { cur += '"'; i++ }
      else if (c === '"') inQuotes = false
      else cur += c
    } else {
      if (c === ',') { out.push(cur); cur = '' }
      else if (c === '"') inQuotes = true
      else cur += c
    }
  }
  out.push(cur)
  return out
}

function escapeCsv(v) {
  if (v === null || v === undefined) return ''
  const s = String(v)
  if (/[",\n\r]/.test(s)) return `"${s.replace(/"/g, '""')}"`
  return s
}

// Walk lines, build question blocks (same parser as build-per-stage-math).
// Matches the renamed 2026-05-28 stage "discovery:canUserAccessRag + vectorSearchResult"
// plus all earlier forms (preDiscovery:shouldRetrieve+getKeywords, etc.).
const STAGE_KEY_RE = /^[a-zA-Z][a-zA-Z0-9]*(:[a-zA-Z0-9+ ]+)+$/

const blocks = []
let current = null

for (const line of raw.split('\n')) {
  const fields = parseCsvLine(line)
  const head = fields[0]
  if (head === 'User') {
    if (current) blocks.push(current)
    current = { question: '', answerLength: null, rows: [], totalRaw: null }
  } else if (head === 'Question' && current) {
    current.question = fields[1] || ''
  } else if (head === 'Answer Length' && current) {
    current.answerLength = fields[1] || ''
  } else if (current && head && STAGE_KEY_RE.test(head)) {
    current.rows.push({ stage: head, timestamp: fields[1] || '', delta: fields[2] || '' })
  } else if (current && head === 'Total') {
    current.totalRaw = fields[2] || fields[1] || ''
  }
}
if (current) blocks.push(current)

if (!blocks.length) {
  console.error('No question blocks found.')
  process.exit(1)
}

// Sort each block's rows by timestamp for clean output (new vectorSearch stage
// is otherwise out of chronological order in the DOM).
function tsToMs(ts) {
  const m = String(ts || '').match(/^(\d{1,2}):(\d{2}):(\d{2})(?:\.(\d+))?$/)
  if (!m) return null
  return parseInt(m[1], 10) * 3600000 + parseInt(m[2], 10) * 60000
    + parseInt(m[3], 10) * 1000 + (m[4] ? parseInt(m[4].padEnd(3, '0').slice(0, 3), 10) : 0)
}

const HEADER = ['STAGE', 'TIMESTAMP', 'DELTA (MS)']
const lines = []

blocks.forEach((b, idx) => {
  if (idx > 0) lines.push('') // blank line between blocks

  lines.push(['Question', b.question].map(escapeCsv).join(','))
  lines.push(['Answer Length', String(b.answerLength || '')].map(escapeCsv).join(','))
  lines.push(HEADER.join(','))

  // Sort chronologically, then re-compute the delta as a signed string so the
  // share file always shows +N (matching last week's "+54", "+1635" style).
  const sorted = b.rows
    .map((r) => ({ ...r, _ms: tsToMs(r.timestamp) }))
    .filter((r) => r._ms != null)
    .sort((a, c) => a._ms - c._ms)

  let prevMs = null
  // Strip ".fff" from timestamps so they appear as HH:MM:SS (matches Husam's
  // last-week format).
  function tsTrunc(ts) {
    const m = String(ts || '').match(/^(\d{1,2}:\d{2}:\d{2})/)
    return m ? m[1] : ts
  }
  for (const r of sorted) {
    let delta = ''
    if (prevMs == null) delta = '-'
    else {
      const d = r._ms - prevMs
      delta = (d >= 0 ? '+' : '') + d
    }
    lines.push([r.stage, tsTrunc(r.timestamp), delta].map(escapeCsv).join(','))
    prevMs = r._ms
  }
  // Extract just the "NNNN ms" portion if present
  const totalMatch = String(b.totalRaw || '').match(/\d+\s*ms/i)
  lines.push(['Total', '', totalMatch ? totalMatch[0] : b.totalRaw || ''].map(escapeCsv).join(','))
})

fs.writeFileSync(outputPath, lines.join('\n') + '\n', 'utf8')
console.log(`Questions parsed: ${blocks.length}`)
console.log(`CSV written: ${outputPath}`)
